import{c as d,Q as a,j as r,m as e}from"./chunks/framework.BIK1AyNB.js";const u=JSON.parse('{"title":"🥕 食物与农耕","description":"","frontmatter":{},"headers":[],"relativePath":"food-farming/index.md","filePath":"food-farming/index.md","lastUpdated":1778824715000}'),l={name:"food-farming/index.md"};function i(h,t,o,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="🥕-食物与农耕" tabindex="-1">🥕 食物与农耕 <a class="header-anchor" href="#🥕-食物与农耕" aria-label="Permalink to &quot;🥕 食物与农耕&quot;">​</a></h1><h2 id="🌱-作物种植" tabindex="-1">🌱 作物种植 <a class="header-anchor" href="#🌱-作物种植" aria-label="Permalink to &quot;🌱 作物种植&quot;">​</a></h2><h3 id="种植参数" tabindex="-1">种植参数 <a class="header-anchor" href="#种植参数" aria-label="Permalink to &quot;种植参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>作物</th><th>生长天数</th><th>需水量</th><th>产量</th><th>病害风险</th><th>备注</th></tr></thead><tbody><tr><td>卷心菜 (Cabbage)</td><td>14 天</td><td>高 (100/天)</td><td>6</td><td>高</td><td>生长最快，但吃多会掉体重</td></tr><tr><td>土豆 (Potato)</td><td>26 天</td><td>中 (85/天)</td><td>4</td><td>低</td><td>保质期 14 天，最耐储存</td></tr><tr><td>番茄 (Tomato)</td><td>18 天</td><td>中 (85/天)</td><td>5</td><td>中</td><td>可直接吃，不增加不快乐</td></tr><tr><td>胡萝卜 (Carrot)</td><td>12 天</td><td>中 (85/天)</td><td>4</td><td>低</td><td>生长快，适合和卷心菜轮作</td></tr><tr><td>西兰花 (Broccoli)</td><td>30 天</td><td>中 (85/天)</td><td>5</td><td>低</td><td>很慢但产量稳定</td></tr><tr><td>萝卜 (Radish)</td><td>17 天</td><td>中 (85/天)</td><td>6</td><td>中</td><td>—</td></tr><tr><td>草莓 (Strawberry)</td><td>22 天</td><td>中 (85/天)</td><td>3</td><td>高</td><td>很美味但产量低，不实用</td></tr></tbody></table><h3 id="农耕流程" tabindex="-1">农耕流程 <a class="header-anchor" href="#农耕流程" aria-label="Permalink to &quot;农耕流程&quot;">​</a></h3><ol><li><strong>挖地</strong> — 空手或铲子在土地上右键「挖地」</li><li><strong>播种</strong> — 种子右键挖过的地，每格可种 1 个作物</li><li><strong>浇水</strong> — 作物缺水会生长缓慢。用水桶/水瓶浇水</li><li><strong>检查</strong> — 每阶段右键作物「检查」可获农耕经验</li><li><strong>收获</strong> — 完全长成后右键收获</li></ol><h3 id="病害管理" tabindex="-1">病害管理 <a class="header-anchor" href="#病害管理" aria-label="Permalink to &quot;病害管理&quot;">​</a></h3><ul><li>每种病害有独立阶段，不及时处理会蔓延到相邻作物</li><li>喷雾器（烟蒂 x5 + 水）可治霉菌</li><li>不想管病害：土豆和胡萝卜病害风险低，几乎不会生病</li><li>间隔种植不同作物可减少病害扩散</li></ul><h2 id="🍳-烹饪" tabindex="-1">🍳 烹饪 <a class="header-anchor" href="#🍳-烹饪" aria-label="Permalink to &quot;🍳 烹饪&quot;">​</a></h2><h3 id="基础食谱" tabindex="-1">基础食谱 <a class="header-anchor" href="#基础食谱" aria-label="Permalink to &quot;基础食谱&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜品</th><th>材料</th><th>饥饿</th><th>无聊</th><th>不快乐</th><th>备注</th></tr></thead><tbody><tr><td>炒菜 (Stir Fry)</td><td>任意食材 x1 + 煎锅</td><td>-20</td><td>0</td><td>0</td><td>基础热食</td></tr><tr><td>炖菜 (Stew)</td><td>任意食材 x1 + 炖锅</td><td>-25</td><td>0</td><td>0</td><td>比炒菜更好</td></tr><tr><td>汤 (Soup)</td><td>任意食材 x1 + 汤锅</td><td>-20</td><td>-5</td><td>0</td><td>减少无聊</td></tr><tr><td>沙拉 (Salad)</td><td>蔬菜 x1 + 碗</td><td>-15</td><td>0</td><td>0</td><td>不加热，无需电</td></tr><tr><td>烤鱼/烤肉 (Roast)</td><td>肉 x1 + 烤盘</td><td>-30</td><td>-5</td><td>0</td><td>饱食度最高</td></tr><tr><td>三明治 (Sandwich)</td><td>面包 x1 + 任意食材</td><td>-25</td><td>0</td><td>0</td><td>不需要锅</td></tr></tbody></table><h3 id="调料效果" tabindex="-1">调料效果 <a class="header-anchor" href="#调料效果" aria-label="Permalink to &quot;调料效果&quot;">​</a></h3><p>在食谱中加入调料可以显著提升效果：</p><ul><li>盐 (Salt)、胡椒 (Pepper) → 减少无聊和不快乐</li><li>ketchup、芥末 (Mustard) → 增加饱食度</li><li>多种调料叠加效果更好</li></ul><h3 id="变质机制" tabindex="-1">变质机制 <a class="header-anchor" href="#变质机制" aria-label="Permalink to &quot;变质机制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>状态</th><th>能否烹饪</th><th>备注</th></tr></thead><tbody><tr><td>新鲜 Fresh</td><td>正常</td><td>✅</td><td>满效果</td></tr><tr><td>不新鲜 Stale</td><td>-30% 饱食度</td><td>✅</td><td>烹饪 3 级前不要吃</td></tr><tr><td>腐烂 Rotting</td><td>-90% 饱食度, 中毒风险</td><td>烹饪 7 级可用</td><td>烹饪 4 级前必中毒（除非 Iron Gut）</td></tr><tr><td>完全腐烂</td><td>消失</td><td>❌</td><td>不及时处理会在容器里烂掉</td></tr></tbody></table><h2 id="🧊-食物保存" tabindex="-1">🧊 食物保存 <a class="header-anchor" href="#🧊-食物保存" aria-label="Permalink to &quot;🧊 食物保存&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>保质期延长</th><th>设备需求</th></tr></thead><tbody><tr><td>常温</td><td>基准</td><td>无</td></tr><tr><td>冰箱 (Fridge)</td><td>x5</td><td>冰箱 + 电/发电机</td></tr><tr><td>冷冻柜 (Freezer)</td><td>x25</td><td>冷冻柜 + 电/发电机</td></tr><tr><td>腌制罐 (Jar)</td><td>永久（~90 天）</td><td>空罐 + 锅盖 + 醋 + 糖 + 水</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">断电后的食物管理</p><p>水电在 0-30 天内随机断供。断电后冰箱保鲜只维持约 2 天。提前准备：</p><ol><li>发电机 + 汽油 → 让冰箱继续工作</li><li>把腐烂食材扔进堆肥桶 → 变成肥料</li><li>多钓鱼 → 鱼不会停水</li><li>腌制罐存储长期食物</li></ol></div>',19)])])}const x=d(l,[["render",i]]);export{u as __pageData,x as default};
